  Do ..GetUniqueParentRepByChildRepCall(reqObj.ChildRep, reqObj.ChildDomainNcid, reqObj.ChildRepContextNcid,reqObj.ChildDomainRelationship,reqObj.RelationshipTypeNcid,reqObj.ParentRepContextNcid,.text)

