  //set hddObj.RelationshipTypeNcid = reqObj.RelationshipTypeNcid
  //set hddObj.ParentRepContextNcid = reqObj.ParentRepContextNcid
  set hddObj.Rep = text	  
  set hddObj.Index = reqObj.Index
  Do list.Insert(hddObj)
  set listInd = pRequest.listOfHddNcidObj.Next(listInd)
}
set pResponse = ##class(IHC.ITF.ITFCOMMON.HDD.Interface.LookupResponse).%New()
set pResponse.listOfHDDobj = list

Quit $$$OK


  try 
  {
 	Set resp = ""
 	set resp = ..GetUniqueParentRepByChildRepFromCache(childRep, childDomainNcid, childRepContextNcid, childDomainRelationship, relationshipTypeNcid, parentRepContextNcid)
 	$$$TRACE(" From Cache GetUniqueParentRepByChildRepFromCache .."_resp)


 	if (resp '= ""){
	 	Set rep = resp
	  	return
	}	
	set servicePort = ##class(HddInterfaceService.InterfaceServicePort).%New()
	set servicePort.Location = ..Location
	$$$TRACE(" From Cache GetUniqueParentRepByChildRepFromCache ..Before WebService Call ")
	Set code = servicePort.getUniqueParentRepByChildRep(childRep, childDomainNcid, childRepContextNcid, childDomainRelationship, relationshipTypeNcid, parentRepContextNcid, ..dbEnv, 0)
	$$$TRACE(" From Cache GetUniqueParentRepByChildRepFromCache Adter WebService Call ")
	if $GET(code){
		Set rep = code.text	
		Do ..InsertValuesToHddUniqueParentRepByChildRepCache(childRep, childDomainNcid, childRepContextNcid, childDomainRelationship, relationshipTypeNcid, parentRepContextNcid,rep)
		$$$TRACE(" GOT the Resp .."_rep)	
		Quit
	}else{
		Set rep = ""
		}
 } 
