	#dim reqObj As IHC.ITF.ITFCOMMON.HDD.Interface.HddObject
	set listInd = pRequest.listOfHddRepObj.Next("")
	set list = ##class(%ListOfObjects).%New()
	set ncid = ""

	while ( listInd '= "")
	{
		set rep = ""
	  	set reqObj = pRequest.listOfHddRepObj.GetAt(listInd)	  	
	  	Do ..GetUniqueRepByNcid(reqObj.NCID, reqObj.Context, .rep)	  		
	  	// Following lines are added by Sushant to use default context - 10/06/2015
	  	if ((rep="")&&..MimicTuxedoServiceCall&&(..DefaultContextValue'=""))
	  	{      
	  		For i = 1 : 1 : $LENGTH(..DefaultContextValue, ","){
 				Set wContext = $PIECE(..DefaultContextValue, ",", i)
   				Do ..GetUniqueRepByNcid(reqObj.NCID, wContext, .rep)
   				quit:rep'=""
	  		}
	  	}
	  	// End Add

	  set hddObj = ##class(IHC.ITF.ITFCOMMON.HDD.Interface.HddObject).%New()
	  set hddObj.Comment = "Get Unique Representation for Ncid"
	  set hddObj.NCID = reqObj.NCID
	  set hddObj.Context = reqObj.Context
	  set hddObj.Domain = ""
	  set hddObj.Rep = rep
	  set hddObj.Index = reqObj.Index
	  Do list.Insert(hddObj)
	  set listInd = pRequest.listOfHddRepObj.Next(listInd)
	}

	set pResponse = ##class(IHC.ITF.ITFCOMMON.HDD.Interface.LookupResponse).%New()
	set pResponse.listOfHDDobj = list

	Quit $$$OK

